<div class="page-title clearfix"><h1>Almacenes</h1></div><div class="row"><div class="col-md-4"><div class="card card-body text-center"><small>Productos activos</small><h2><?php echo(int)$active_products; ?></h2></div></div><div class="col-md-4"><div class="card card-body text-center"><small>Almacenes activos</small><h2><?php echo(int)$active_warehouses; ?></h2></div></div><div class="col-md-4"><div class="card card-body text-center"><small>Existencia total controlada</small><h2><?php echo esc(to_decimal_format($total_stock)); ?></h2></div></div></div><div class="card mt15"><div class="card-body"><div class="row"><?php foreach(['Entradas recientes'=>$recent_entries,'Salidas recientes'=>$recent_exits,'Ajustes recientes'=>$recent_adjustments]as$title=>$rows): ?><div class="col-md-4"><h5><?php echo$title; ?></h5><?php if($rows): ?><ul class="list-group list-group-flush"><?php foreach($rows as$r): ?><li class="list-group-item"><a href="<?php echo get_uri('warehouses/movements/view/'.$r->id); ?>"><?php echo esc($r->folio); ?></a> · <?php echo esc($r->warehouse_name); ?><br><small><?php echo esc($r->confirmed_at); ?></small></li><?php endforeach; ?></ul><?php else: ?><p class="text-muted">Sin movimientos.</p><?php endif; ?></div><?php endforeach; ?></div></div></div>
